use super::*;
fn chapter(id:&str,position:i64)->Chapter{Chapter{id:id.into(),project_id:"project".into(),title:format!("Chapter {id} مِ 中文"),position}}
fn model()->ManuscriptParts{ManuscriptParts{schema_version:1,parts:vec![ManuscriptPart{id:"a".into(),title:"الجزء 明 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}".into(),hidden:false},ManuscriptPart{id:"b".into(),title:"Hidden".into(),hidden:true}],chapters:vec![ChapterPart{chapter_id:"one".into(),part_id:"a".into()},ChapterPart{chapter_id:"two".into(),part_id:"b".into()},ChapterPart{chapter_id:"three".into(),part_id:"a".into()}]}}
#[test]fn part_order_and_hidden_headings_never_reorder_canonical_chapters(){let chapters=vec![chapter("one",0),chapter("two",1),chapter("three",2)];let original=chapters.clone();let mut model=model();let assignments=model.chapters.clone();let first=chapter_heading(&model,"one");assert_eq!(first,chapter_heading(&model,"three"));assert_eq!(chapter_heading(&model,"two"),None);move_part(&mut model,"a",1).unwrap();assert_eq!(model.parts[0].id,"b");assert_eq!(model.chapters,assignments);assert_eq!(chapter_heading(&model,"one"),first);assert_eq!(chapters,original);let text=overview(&model,&chapters,0);assert!(text.contains("Chapter 0"));assert!(text.contains("Heading hidden"));}
#[test]fn removing_a_part_unassigns_only_its_chapters_and_retains_other_part(){let mut model=model();let retained=model.parts[1].clone();remove_part(&mut model,"a").unwrap();assert_eq!(model.parts,vec![retained]);assert_eq!(model.chapters,vec![ChapterPart{chapter_id:"two".into(),part_id:"b".into()}]);assert!(remove_part(&mut model,"unknown").is_err());assert!(overview(&model,&[chapter("one",0),chapter("two",1)],1).contains("Ungrouped chapters\n  Chapter 1"));}
#[test]fn exact_unicode_assignments_require_captured_identity_and_missing_history_is_explicit(){let mut model=model();let canonical=vec![chapter("one",0),chapter("two",1)];let before=model.clone();assert!(assign(&mut model,&canonical,"foreign",Some("a")).is_err());assert!(assign(&mut model,&canonical,"one",Some("missing")).is_err());assert_eq!(model,before);assign(&mut model,&canonical,"one",None).unwrap();assert!(!model.chapters.iter().any(|a|a.chapter_id=="one"));assign(&mut model,&canonical,"one",Some("a")).unwrap();assert_eq!(chapter_heading(&model,"one").unwrap(),"الجزء 明 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}");assert!(overview(&model,&canonical,1).contains("Unavailable historical chapter assignment"));}

/// Root calls this only in its serialized opt-in GTK harness. Synthetic entry
/// preedit is lifecycle coverage, not a claim of physical IME qualification.
pub(crate) fn run(binaries:&Path){
    assert_eq!(desk::WINDOWS.with(|w|w.borrow().len()),0);let directory=tempfile::tempdir().unwrap();let data=directory.path().join("parts-data");let cache=directory.path().join("parts-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let novel=rpc(&client,"create_novel",json!({"title":"Parts fixture مِ 中文"}));let pid=novel["project"]["id"].as_str().unwrap();let sid=novel["scene"]["id"].as_str().unwrap();let first=novel["scene"]["chapterId"].as_str().unwrap().to_owned();let second=rpc(&client,"create_chapter",json!({"projectId":pid,"title":"第二章 مِ"}))["id"].as_str().unwrap().to_owned();let third=rpc(&client,"create_chapter",json!({"projectId":pid,"title":"第三章 e\u{301}"}))["id"].as_str().unwrap().to_owned();let initial=rpc(&client,"open_project",json!({"projectId":pid}));let original=rpc(&client,"load_scene",json!({"sceneId":sid}));let ids=vec![first.clone(),second.clone(),third.clone()];let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.scene_id==sid&&p.open.get()&&p.pending.get()==0));a.organize_parts();let page=a.parts_pages.borrow().last().unwrap().clone();wait(||page.loaded.get());let marker=rpc(&a.client,"sync_cursor",json!({}));let (_discarded_part,_)=author(&page,&ids);assert!(page.dirty.get());assert!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})).is_null());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    page.title.emit_by_name::<()>("preedit-changed",&[&"synthetic preedit"]);assert!(page.composing.get());assert!(save(&page,&a).is_err());page.title.emit_by_name::<()>("preedit-changed",&[&""]);assert!(!page.composing.get());a.desk.choices.borrow_mut().push_back(desk::SaveChoice::Cancel);a.open_scene(sid,false);assert_eq!(a.current_widget(),Some(page.widget.clone().upcast()));assert!(page.dirty.get());a.desk.choices.borrow_mut().push_back(desk::SaveChoice::Discard);a.open_scene(sid,false);wait(||a.current_widget()!=Some(page.widget.clone().upcast()));assert!(!page.dirty.get());assert!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})).is_null());assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);
    a.organize_parts();let page=a.parts_pages.borrow().last().unwrap().clone();wait(||page.loaded.get());let (part_a,part_b)=author(&page,&ids);let exact=page.draft.borrow().clone();a.desk.choices.borrow_mut().push_back(desk::SaveChoice::Save);a.open_scene(sid,false);wait(||!page.dirty.get()&&a.current_widget()!=Some(page.widget.clone().upcast()));wait(||tree_rows(&a.outline).iter().filter(|r|r.2=="part").count()==2);let rows=tree_rows(&a.outline);assert_eq!(rows.iter().filter(|r|r.2=="chapter").map(|r|r.1.clone()).collect::<Vec<_>>(),ids);assert_eq!(rows.iter().filter(|r|r.2=="part").map(|r|r.1.as_str()).collect::<Vec<_>>(),vec![part_a.as_str(),part_a.as_str()]);assert!(!rows.iter().any(|r|r.2=="part"&&r.1==part_b));assert_eq!(a.book.children().iter().filter_map(|w|w.clone().downcast::<gtk::Expander>().ok().and_then(|e|e.label().map(|s|s.to_string()))).collect::<Vec<_>>(),initial["chapters"].as_array().unwrap().iter().map(|c|c["title"].as_str().unwrap().to_owned()).collect::<Vec<_>>());assert_eq!(rpc(&a.client,"open_project",json!({"projectId":pid})),initial);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);
    a.organize_parts();let stale=a.parts_pages.borrow().last().unwrap().clone();wait(||stale.loaded.get());stale.part.set_active_id(Some(&part_a));stale.title.set_text("Local stale rename مِ");let local=stale.draft.borrow().clone();rpc(&a.client,"rename_chapter",json!({"chapterId":first,"title":"Externally renamed chapter 中文"}));a.refresh_parts_outline();wait(||a.tree.tooltip_text().is_some_and(|t|t.contains("Canonical chapters changed")));assert!(a.parts_outline.borrow().is_none());assert!(!tree_rows(&a.outline).iter().any(|r|r.2=="part"));assert!(save(&stale,&a).is_err());assert!(stale.dirty.get());assert_eq!(*stale.draft.borrow(),local);a.load_index();wait(||tree_rows(&a.outline).iter().any(|r|r.2=="chapter"&&r.0=="Externally renamed chapter 中文")&&tree_rows(&a.outline).iter().filter(|r|r.2=="part").count()==2);stale.discard();assert_eq!(*stale.draft.borrow(),exact);
    a.organize_parts();let detached=a.parts_pages.borrow().last().unwrap().clone();wait(||detached.loaded.get());detached.part.set_active_id(Some(&part_a));detached.title.set_text("Detached Part title مِ e\u{301}");a.detach_current();let child=desk::WINDOWS.with(|w|w.borrow().last().unwrap().clone());assert!(!Rc::ptr_eq(&a,&child));assert!(child.parts_pages.borrow().iter().any(|p|Rc::ptr_eq(p,&detached)));assert!(!a.parts_pages.borrow().iter().any(|p|Rc::ptr_eq(p,&detached)));a.close();wait(||a.desk.is_closed());save(&detached,&child).unwrap();let persisted=rpc(&child.client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));assert_eq!(persisted["payload"]["manuscriptParts"]["parts"].as_array().unwrap().iter().find(|p|p["id"]==part_a).unwrap()["title"],"Detached Part title مِ e\u{301}");assert_eq!(rpc(&child.client,"load_scene",json!({"sceneId":sid})),original);child.close();wait(||desk::WINDOWS.with(|w|w.borrow().is_empty()));
}
fn author(page:&Rc<PartsPage>,chapters:&[String])->(String,String){find_button(page.widget.upcast_ref(),"Add Part").unwrap().clicked();let a=page.part.active_id().unwrap().to_string();page.title.set_text("الجزء 明 e\u{301} 👩🏽‍🚀 𠀀 \u{e000}");page.chapter.set_active_id(Some(&chapters[0]));page.membership.set_active_id(Some(&a));find_button(page.widget.upcast_ref(),"Add Part").unwrap().clicked();let b=page.part.active_id().unwrap().to_string();page.title.set_text("Hidden Part heading");page.hidden.set_active(true);page.chapter.set_active_id(Some(&chapters[1]));page.membership.set_active_id(Some(&b));page.chapter.set_active_id(Some(&chapters[2]));page.membership.set_active_id(Some(&a));(a,b)}
fn wait(condition:impl Fn()->bool){let start=std::time::Instant::now();let context=glib::MainContext::default();while !condition(){while context.pending(){context.iteration(false);}assert!(start.elapsed()<Duration::from_secs(20),"Parts GTK callback timed out");std::thread::sleep(Duration::from_millis(5));}while context.pending(){context.iteration(false);}}
fn rpc(client:&Process,op:&str,args:Value)->Value{let result=Rc::new(RefCell::new(None));let out=result.clone();client.rpc(op,args,move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let reply=result.borrow_mut().take().unwrap().unwrap();reply}
fn save(page:&Rc<PartsPage>,owner:&Rc<Workspace>)->Result<(),String>{let result=Rc::new(RefCell::new(None));let out=result.clone();page.save(owner,move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let reply=result.borrow_mut().take().unwrap();reply}
fn find_button(widget:&gtk::Widget,name:&str)->Option<gtk::Button>{if let Ok(button)=widget.clone().downcast::<gtk::Button>(){if button.label().as_deref()==Some(name){return Some(button);}}widget.clone().downcast::<gtk::Container>().ok().and_then(|c|c.children().iter().find_map(|w|find_button(w,name)))}
fn tree_rows(model:&gtk::TreeStore)->Vec<(String,String,String)>{fn visit(model:&gtk::TreeStore,parent:Option<&gtk::TreeIter>,out:&mut Vec<(String,String,String)>){let Some(iter)=model.iter_children(parent)else{return;};loop{out.push((model.value(&iter,0).get().unwrap(),model.value(&iter,1).get().unwrap(),model.value(&iter,2).get().unwrap()));visit(model,Some(&iter),out);if !model.iter_next(&iter){break;}}}let mut rows=vec![];visit(model,None,&mut rows);rows}
